/bin/bash -lc "cd /work && python - <<'PY'
import mujoco
from sim import Sim
sim=Sim(); m=sim.model
# bodies
for i in range(m.nbody):
    name=mujoco.mj_id2name(m,mujoco.mjtObj.mjOBJ_BODY,i)
    if name and ('hand' in name or 'grip' in name or 'finger' in name or 'ee' in name):
        print('body',i,name)
print('---sites---')
for i in range(m.nsite):
    name=mujoco.mj_id2name(m,mujoco.mjtObj.mjOBJ_SITE,i)
    if name and ('hand' in name or 'grip' in name or 'finger' in name or 'ee' in name):
        print('site',i,name)
print('---joints---')
for i in range(m.njnt):
    name=mujoco.mj_id2name(m,mujoco.mjtObj.mjOBJ_JOINT,i)
    if name and ('finger' in name or 'hand' in name):
        print('joint',i,name,'type',m.jnt_type[i])
PY"

